try:
    compressed_payload = base64.b64decode(
        ''.join(PAYLOAD_PARTS),
        validate=True,
    )
    source_bytes = zlib.decompress(compressed_payload)
except Exception as error:
    raise SystemExit(
        f'ERRO: arquivo Master V25 corrompido ou incompleto: {error}'
    ) from error

actual_sha256 = hashlib.sha256(source_bytes).hexdigest()
if actual_sha256 != EXPECTED_SHA256:
    raise SystemExit(
        'ERRO: a integridade do código Master V25 não confere.'
    )

source = source_bytes.decode('utf-8')

compiled = compile(
    source,
    'aplicar-igreja-batista-eden-master-v2-interno-v25.py',
    'exec',
)

exec(
    compiled,
    {
        '__name__': '__main__',
        '__file__': __file__,
    },
)
